def min_coins(coins, amount):
    best = [float('inf')] * (amount + 1)
    best[0] = 0
    for total in range(1, amount + 1):
        for coin in coins:
            if coin <= total:
                best[total] = min(best[total], best[total - coin] + 1)
    return -1 if best[amount] == float('inf') else best[amount]

print(min_coins([1, 3, 4], 6))
print(min_coins([1, 5, 10, 25], 63))
print(min_coins([2], 3))

